/**
 * flightwake-mod — Claude Code's add-on layer over flightwake's Markdown records (docs/plans/mods.md).
 * register only assembles: each feature lives in its own module under features/ and is switched by its
 * userConfig field. A feature that throws while registering is dropped alone; at run time the engine skips a
 * failing hook and the chain goes on, so one feature's failure never reaches the others or the person's work.
 */
import type { PluginOptions, Register } from 'claude-code'

import { registerStateInject } from './features/state-inject'
import { registerBand } from './features/band'
import { registerRecorder } from './features/recorder'
import { registerTripwire } from './features/tripwire'
import { registerRoleGuard } from './features/role-guard'
import { registerStatus } from './features/status'

/** userConfig field → default, mirrored from .claude-plugin/plugin.json (F5 is opt-in). */
export const DEFAULTS = { stateInject: true, band: true, recorder: true, tripwire: true, roleGuard: false } as const

export const isEnabled = (options: PluginOptions, key: keyof typeof DEFAULTS): boolean =>
  typeof options[key] === 'boolean' ? options[key] === true : DEFAULTS[key]

// Each call is spelled out (not looped over a table): the engine's loader only accepts `on` passed to a function
// imported by name. Each is wrapped so a feature that throws while registering stays off alone.
export const register: Register = (on, options) => {
  if (isEnabled(options, 'stateInject')) try { registerStateInject(on) } catch {} // F1
  if (isEnabled(options, 'band')) try { registerBand(on) } catch {} // F2
  if (isEnabled(options, 'recorder')) try { registerRecorder(on) } catch {} // F3
  if (isEnabled(options, 'tripwire')) try { registerTripwire(on) } catch {} // F4
  if (isEnabled(options, 'roleGuard')) try { registerRoleGuard(on) } catch {} // F5
  // /fw-mod: not a switch — it is how the switches are seen
  try {
    registerStatus(on, {
      stateInject: isEnabled(options, 'stateInject'), band: isEnabled(options, 'band'), recorder: isEnabled(options, 'recorder'),
      tripwire: isEnabled(options, 'tripwire'), roleGuard: isEnabled(options, 'roleGuard'),
    })
  } catch {}
}

files.hooks/features/state-inject.ts:
/**
 * F1 STATE snapshot into the system prompt (docs/plans/mods.md, revised; DECISIONS 2026-10-05).
 * One snapshot per session id, taken on session.start (pre-warm) or lazily on the first prompt.compose, then
 * reused: the section never changes mid-session, so the prompt cache behind it stays valid. /clear (session.end
 * reason 'clear') drops it; the next compose retakes it under the new id. Read-only; a failure injects nothing.
 */
import { atom, read, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'

import { M, STATE_REL, fwContext, isUninitializedState, readRel } from '../lib/core'
import type { Io, Lang } from '../lib/core'

const SECTION_ID = 'flightwake-mod:state'
/** DECISIONS 2026-10-05: STATE text over this many characters is injected condensed. */
const LIMIT = 6000

const snapshotRef = atom({ plugin: 'flightwake-mod', key: 'stateSnapshot' } as const, null)

type Snap = { sessionId: string; text: string | null }

// Local copy of IO_OF_TEMPLATE (hooks/lib/core.ts): `$` must not cross an import.
function ioOf($: EngineInterface): Io {
  return {
    root: async () => { try { return (await $.session.root()).replace(/\/+$/, '') } catch { return '' } },
    sessionId: async () => { try { return await $.session.id() } catch { return '' } },
    exists: async (p) => { try { return await $.fs.exists(p) } catch { return false } },
    read: async (p) => {
      try { if (!(await $.fs.exists(p))) return null; const t = await $.fs.read(p); return typeof t === 'string' ? t : null } catch { return null }
    },
    git: async (args, cwd) => {
      try { const r = await $.process.run(['git', '--no-optional-locks', ...args], { cwd, timeoutMs: 5000 }); return r.exitCode === 0 ? r.stdout.trim() : null } catch { return null }
    },
    settings: async () => { try { return await $.settings.read({}) } catch { return {} } },
  }
}

/** STATE split into its frontmatter block and its top-level "# " sections (comments and fenced code ignored). */
function splitState(text: string): { front: string; sections: string[] } {
  const lines = text.split(/\r?\n/)
  let i = 0
  let front: string[] = []
  if (lines[0]?.trim() === '---') {
    const end = lines.findIndex((l, k) => k > 0 && l.trim() === '---')
    if (end > 0) { front = lines.slice(0, end + 1); i = end + 1 }
  }
  const sections: string[][] = []
  let inComment = false
  let inFence = false
  for (; i < lines.length; i++) {
    const line = lines[i] ?? ''
    let isHeading = false
    if (inComment) {
      if (line.includes('-->')) inComment = false
    } else if (inFence) {
      if (/^\s*(```|~~~)/.test(line)) inFence = false
    } else if (/^\s*(```|~~~)/.test(line)) {
      inFence = true
    } else if (line.trimStart().startsWith('<!--')) {
      if (!line.includes('-->')) inComment = true
    } else if (/^# /.test(line)) {
      isHeading = true
    }
    if (isHeading) sections.push([line])
    else sections[sections.length - 1]?.push(line)
  }
  return { front: front.join('\n'), sections: sections.map((s) => s.join('\n').replace(/\s+$/, '')) }
}

/** `text` cut at a line boundary to at most `max` characters (the "…" marker included); unchanged when it fits. */
function trimLines(text: string, max: number): string {
  if (text.length <= max) return text
  const cut = text.slice(0, Math.max(0, max - 2))
  const nl = cut.lastIndexOf('\n')
  return `${nl > 0 ? cut.slice(0, nl) : cut}\n…`
}

/** The condensed STATE: frontmatter (health), the 2nd and 3rd top-level sections, each trimmed if still over LIMIT. */
function condense(text: string): string {
  const { front, sections } = splitState(text)
  const kept = [sections[1], sections[2]].filter((s): s is string => typeof s === 'string')
  const frontKept = front ? trimLines(front, 1500) : ''
  const join = (b: string[]) => [frontKept, ...b].filter(Boolean).join('\n\n')
  if (join(kept).length <= LIMIT) return join(kept)
  const budget = LIMIT - frontKept.length - 2 * (kept.length + 1)
  if (kept.length === 0) return join([trimLines(sections.join('\n\n') || text, Math.max(200, budget))])
  const each = Math.max(200, Math.floor(budget / kept.length))
  return join(kept.map((s) => trimLines(s, each)))
}

function snapshotText(lang: Lang, state: string): string {
  if (isUninitializedState(state)) {
    return M(lang, {
      en: 'flightwake: .flightwake/STATE.md is not initialized yet. Run /fw-coldstart first.',
      'zh-TW': 'flightwake:.flightwake/STATE.md 尚未初始化,請先執行 /fw-coldstart。',
      'zh-CN': 'flightwake:.flightwake/STATE.md 尚未初始化,请先执行 /fw-coldstart。',
      ja: 'flightwake: .flightwake/STATE.md はまだ初期化されていません。先に /fw-coldstart を実行してください。',
    })
  }
  const header = M(lang, {
    en: 'flightwake: this is .flightwake/STATE.md as of the last wrap-up, a snapshot taken at session start. Check the git state before acting on it. /fw-coldstart still checks how far STATE lags and reads the latest record.',
    'zh-TW': 'flightwake:以下是 .flightwake/STATE.md 在上次收尾時的內容,於 session 開始時取的快照。動手前請先核對 git 狀態。落後量檢查與最新 record 的閱讀仍由 /fw-coldstart 負責。',
    'zh-CN': 'flightwake:以下是 .flightwake/STATE.md 在上次收尾时的内容,于 session 开始时取的快照。动手前请先核对 git 状态。落后量检查与最新 record 的阅读仍由 /fw-coldstart 负责。',
    ja: 'flightwake: 以下は前回の締め時点の .flightwake/STATE.md で、セッション開始時に取ったスナップショットです。作業の前に git の状態を確認してください。遅れの確認と最新 record の読み込みは引き続き /fw-coldstart が行います。',
  })
  if (state.length <= LIMIT) return `${header}\n\n${state.replace(/\s+$/, '')}`
  const n = state.length
  const note = M(lang, {
    en: `(condensed; full file at ${STATE_REL} (${n} characters, over ${LIMIT}); read it when needed. Consider compacting STATE.)`,
    'zh-TW': `(已精簡;完整內容見 ${STATE_REL}(${n} 字元,超過 ${LIMIT});需要時請讀取原檔。建議壓實 STATE。)`,
    'zh-CN': `(已精简;完整内容见 ${STATE_REL}(${n} 字符,超过 ${LIMIT});需要时请读取原文件。建议压实 STATE。)`,
    ja: `(要約済み。全文は ${STATE_REL}(${n} 文字、上限 ${LIMIT} 超)にあります。必要なときに読んでください。STATE の圧縮を検討してください。)`,
  })
  return `${header}\n\n${condense(state)}\n\n${note}`
}

async function takeText(io: Io): Promise<string | null> {
  const ctx = await fwContext(io)
  if (!ctx) return null
  const state = await readRel(io, ctx.root, STATE_REL)
  return state === null ? null : snapshotText(ctx.lang, state)
}

/** The snapshot for the current session id: kept when it already exists, otherwise taken now and stored. */
async function ensureSnapshot($: EngineInterface): Promise<Snap | null> {
  const io = ioOf($)
  const id = await io.sessionId()
  if (!id) return null
  const cur = (await read($, snapshotRef)) as Snap | null
  if (cur && cur.sessionId === id) return cur
  const fresh: Snap = { sessionId: id, text: await takeText(io) }
  // A concurrent taker (session.start vs. the first compose) may have stored one meanwhile: that one wins.
  await update($, snapshotRef, (c) => ((c as Snap | null)?.sessionId === id ? c : fresh))
  return ((await read($, snapshotRef)) as Snap | null) ?? fresh
}

export function registerStateInject(on: On): void {
  on('session.start', {}, async ($, e, next) => {
    const r = await next(e)
    try { await ensureSnapshot($) } catch {}
    return r
  })

  on('session.end', {}, async ($, e, next) => {
    if (e.reason === 'clear') {
      try { await update($, snapshotRef, () => null) } catch {}
    }
    return next(e)
  })

  on('prompt.compose', {}, async ($, e, next) => {
    const r = await next(e)
    if (e.traits.includes('bare')) return r
    try {
      const snap = await ensureSnapshot($)
      if (!snap || !snap.text) return r
      return { sections: [...r.sections.filter((s) => s.id !== SECTION_ID), { id: SECTION_ID, text: snap.text, scope: 'session' as const }] }
    } catch {
      return r
    }
  })
}

files.hooks/features/band.ts:
/**
 * F2 status band above the prompt + one context toast. Contract: docs/plans/mods.md (revised) and hooks/lib/core.ts.
 *
 * The FwBandView ($.state bandView) is computed OUTSIDE rendering (session.start, turn.complete, and after a Bash
 * tool call that reports a commit or branch operation); the ui.render hook only reads it and draws, never runs git.
 * Hints point only at flightwake commands (same wording family as hooks/statusline.mjs); no update check, no network.
 * When the legacy statusline.mjs is the effective statusLine every field would duplicate it, so the band stays
 * quiet and only the one-time context toast remains. Without it the band IS the gauge: always drawn, always with the
 * context percent when Claude Code reports one (2026-10-05, replacing "silent while all is well" — someone with the
 * mod and no gauge otherwise never saw their context use). The mod never edits settings.
 */
import { atom, read, update } from 'claude-code'
import type { EngineInterface, On, RenderElement } from 'claude-code'

import { fwContext, healthOf, isUninitializedState, joinPath, legacyStatuslineActive, M, STATE_REL, stateLag } from '../lib/core'
import type { Io, Lang } from '../lib/core'
import type { FwBandView } from '../../types/index'

const bandView = atom({ plugin: 'flightwake-mod', key: 'bandView' } as const, null)
const bandToastSession = { plugin: 'flightwake-mod', key: 'bandToastSession' } as const

function ioOf($: EngineInterface): Io {
  return {
    root: async () => { try { return (await $.session.root()).replace(/\/+$/, '') } catch { return '' } },
    sessionId: async () => { try { return await $.session.id() } catch { return '' } },
    exists: async (p) => { try { return await $.fs.exists(p) } catch { return false } },
    read: async (p) => {
      try { if (!(await $.fs.exists(p))) return null; const t = await $.fs.read(p); return typeof t === 'string' ? t : null } catch { return null }
    },
    git: async (args, cwd) => {
      try { const r = await $.process.run(['git', '--no-optional-locks', ...args], { cwd, timeoutMs: 5000 }); return r.exitCode === 0 ? r.stdout.trim() : null } catch { return null }
    },
    settings: async () => { try { return await $.settings.read({}) } catch { return {} } },
  }
}

const HOT = 80
const WARM = 60
const LAG_HINT = 3

function hintFor(lang: Lang, v: { health: string; contextPercent: number | null; behind: number | null; justOpened: boolean; isUninitialized?: boolean }): string | null {
  if (v.isUninitialized) return M(lang, {
    en: 'STATE not initialized yet — run /fw-coldstart',
    'zh-TW': 'STATE 尚未初始化——先跑 /fw-coldstart',
    'zh-CN': 'STATE 尚未初始化——先跑 /fw-coldstart',
    ja: 'STATE が未初期化——まず /fw-coldstart',
  })
  if (v.health === 'yellow' || v.health === 'red') return M(lang, {
    en: 'handle unverified items before stacking new work (read STATE)',
    'zh-TW': '先處理未驗證項再疊新工作(讀 STATE)',
    'zh-CN': '先处理未验证项再叠新工作(读 STATE)',
    ja: '未検証の項目を片付けてから新しい作業を積む(STATE を読む)',
  })
  if (v.contextPercent !== null && v.contextPercent >= HOT) return M(lang, {
    en: '/fw-record → /clear → /fw-coldstart',
    'zh-TW': '/fw-record 收尾 → /clear → /fw-coldstart 接手',
    'zh-CN': '/fw-record 收尾 → /clear → /fw-coldstart 接手',
    ja: '/fw-record で締め → /clear → /fw-coldstart で引き継ぎ',
  })
  if (v.behind !== null && v.behind >= LAG_HINT) return M(lang, {
    en: '/fw-record to wrap up',
    'zh-TW': '/fw-record 收尾',
    'zh-CN': '/fw-record 收尾',
    ja: '/fw-record で締める',
  })
  if (v.justOpened) return M(lang, {
    en: 'start with /fw-coldstart',
    'zh-TW': '先跑 /fw-coldstart 接手',
    'zh-CN': '先跑 /fw-coldstart 接手',
    ja: 'まず /fw-coldstart で引き継ぐ',
  })
  return null
}

/** Pure: the view for a set of facts. Language only shapes the hint. */
function viewOf(lang: Lang, f: {
  health: FwBandView['health']
  lag: FwBandView['lagKind']
  behind: number | null
  contextPercent: number | null
  isLegacyGaugeActive: boolean
  justOpened: boolean
  isUninitialized?: boolean
}): FwBandView {
  const hint = hintFor(lang, { health: f.health, contextPercent: f.contextPercent, behind: f.behind, justOpened: f.justOpened, isUninitialized: f.isUninitialized })
  return {
    isLegacyGaugeActive: f.isLegacyGaugeActive,
    health: f.health,
    lagKind: f.lag,
    behind: f.behind,
    contextPercent: f.contextPercent,
    hint,
    // Quiet only when the bottom gauge already shows all of this; otherwise the band stands in for the gauge
    isQuiet: f.isLegacyGaugeActive,
    lang,
  }
}

type Computed = { view: FwBandView; lang: Lang; sessionId: string }

/** Reads the world and builds the view; null when flightwake is not set up here. A template STATE → health unknown + coldstart hint. */
async function compute($: EngineInterface): Promise<Computed | null> {
  const io = ioOf($)
  const ctx = await fwContext(io)
  if (ctx === null) return null
  const text = await io.read(joinPath(ctx.root, STATE_REL))
  if (text === null) return null
  const isUninitialized = isUninitializedState(text)
  const lag = isUninitialized ? null : await stateLag(io, ctx.root)
  let contextPercent: number | null = null
  try {
    const p = (await $.session.usage()).context.percent
    contextPercent = typeof p === 'number' && Number.isFinite(p) ? p : null
  } catch { contextPercent = null }
  let turns = 1
  try { turns = await $.session.turns() } catch { turns = 1 }
  const view = viewOf(ctx.lang, {
    health: isUninitialized ? 'unknown' : healthOf(text),
    lag: lag === null ? 'none' : lag.kind,
    behind: lag !== null && lag.kind === 'behind' ? lag.behind : null,
    contextPercent,
    isLegacyGaugeActive: await legacyStatuslineActive(io),
    justOpened: turns === 0,
    isUninitialized,
  })
  return { view, lang: ctx.lang, sessionId: await io.sessionId() }
}

/** Recompute the view, store it, and toast once per session when context runs hot. Never throws. */
async function refresh($: EngineInterface): Promise<void> {
  try {
    const c = await compute($)
    await update($, bandView, () => c === null ? null : c.view)
    if (c === null || c.sessionId === '' || c.view.contextPercent === null || c.view.contextPercent < HOT) return
    const held = await $.state.get(bandToastSession)
    if (held.value === c.sessionId) return
    // ifVersion: of two refreshes racing in one session only the winner of the write toasts.
    const w = await $.state.set(bandToastSession, c.sessionId, { ifVersion: held.version })
    if (!w.isSet) return
    $.ui.toast(M(c.lang, {
      en: 'flightwake: context is running hot — wrap up with /fw-record, then /clear and /fw-coldstart',
      'zh-TW': 'flightwake:context 快滿了——先 /fw-record 收尾,再 /clear 與 /fw-coldstart 接手',
      'zh-CN': 'flightwake:context 快满了——先 /fw-record 收尾,再 /clear 与 /fw-coldstart 接手',
      ja: 'flightwake:コンテキストが逼迫しています。/fw-record で締めてから /clear と /fw-coldstart へ',
    }), { timeoutMs: 8000 })
  } catch {
    try { await update($, bandView, () => null) } catch {}
  }
}

function lagText(lang: Lang, v: FwBandView): string {
  switch (v.lagKind) {
    case 'dirty':
      return M(lang, { en: 'STATE updating', 'zh-TW': 'STATE 更新中', 'zh-CN': 'STATE 更新中', ja: 'STATE 更新中' })
    case 'error':
      return M(lang, { en: 'STATE lag ?', 'zh-TW': 'STATE 落後量未知 ?', 'zh-CN': 'STATE 落后量未知 ?', ja: 'STATE の遅れ不明 ?' })
    case 'behind': {
      const n = v.behind ?? 0
      return n > 0
        ? M(lang, { en: `STATE ${n}c behind`, 'zh-TW': `STATE 落後 ${n}c`, 'zh-CN': `STATE 落后 ${n}c`, ja: `STATE ${n}c 遅れ` })
        : M(lang, { en: 'STATE in sync', 'zh-TW': 'STATE 同步', 'zh-CN': 'STATE 同步', ja: 'STATE 同期済' })
    }
    default:
      return '' // no-baseline / none: not measured, say nothing
  }
}

export function registerBand(on: On): void {
  on('session.start', {}, async ($, e, next) => {
    const r = await next(e)
    await refresh($)
    return r
  })

  on('turn.complete', {}, async ($, e, next) => {
    const r = await next(e)
    await refresh($)
    return r
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    try {
      if (ran.deny === undefined && ran.isError === undefined) {
        const op = (ran.result as { gitOperation?: { commit?: unknown; branch?: unknown } } | undefined)?.gitOperation
        if (op && (op.commit || op.branch)) await refresh($)
      }
    } catch {}
    return ran
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    try {
      if (e.props.hasSurvey) return next(e)
      const v = await read($, bandView)
      if (!v || v.isQuiet) return next(e)
      const lang = v.lang
      const { Box, Text } = $.ui.resolve(e)
      const color = v.health === 'green' ? 'green' : v.health === 'yellow' ? 'yellow' : v.health === 'red' ? 'red' : undefined
      const lag = lagText(lang, v)
      const pct = v.contextPercent
      const row: unknown[] = [
        h(Text, { bold: true, wrap: 'truncate' }, '✈ flightwake'),
        h(Text, { color, wrap: 'truncate' }, ` · ●${v.health === 'unknown' ? '?' : v.health}`),
      ]
      if (lag) row.push(h(Text, { wrap: 'truncate' }, ` · ${lag}`))
      // Always the percent when known (the band stands in for the gauge); the colour thresholds are unchanged
      if (pct !== null) row.push(h(Text, { color: pct >= HOT ? 'red' : pct >= WARM ? 'yellow' : undefined, wrap: 'truncate' }, ` · ${Math.round(pct)}%`))
      if (v.hint) row.push(h(Text, { dimColor: true, wrap: 'truncate-end' }, ` → ${v.hint}`))
      const tree = h(Box, { width: e.props.bodyColumns, flexDirection: 'row', overflow: 'hidden' }, ...row)
      return tree && typeof tree !== 'string' ? (tree as RenderElement) : next(e)
    } catch {
      return next(e)
    }
  })
}

files.hooks/features/recorder.ts:
/**
 * F3 session flight log + /fw-log (docs/plans/mods.md, F3 as revised 2026-10-05).
 *
 * Observation only: the log holds what this session's tools did (files the agent edited, test/typecheck commands
 * whose completion was observed, commits git reported) and nothing else. It never writes a record, never reads
 * git-visible changes made by other programs, and is kept in $.state per session id (a /clear is a new id → fresh
 * log; a module reload keeps it). No cross-session history.
 *
 * Conservative by design: a command is recorded only when it is recognised (known runner, a package script whose
 * body was read, a command STATE.md declares as verification); the result is pass/fail only for a single plain
 * command with a reliable completion and an exit code. Everything else that is recorded is 'unknown' with a reason.
 */
import { atom, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'

import type { FwFlightLog, FwShellWrite, FwTestRun } from '../../types'
import { M, STATE_REL, fwContext, packageScripts, readRel, relToRoot, tableCell as cell } from '../lib/core'
import type { Io, Lang } from '../lib/core'
import { parseCommand, shellWriteTargets } from '../lib/shell'
import type { Segment } from '../lib/shell'
import { declaredCommands, judge, type Judgment } from '../lib/testcmd'

const flightLog = atom({ plugin: 'flightwake-mod', key: 'flightLog' } as const, null)

const CAP_FILES = 500
const CAP_TESTS = 200
const CAP_COMMITS = 200
const CAP_COMMAND = 300
const CAP_SCRIPT = 200
const LIST_LIMIT = 100

// The Io closure over this file's `$` (IO_OF_TEMPLATE in hooks/lib/core.ts; `$` may not cross an import).
function ioOf($: EngineInterface): Io {
  return {
    root: async () => { try { return (await $.session.root()).replace(/\/+$/, '') } catch { return '' } },
    sessionId: async () => { try { return await $.session.id() } catch { return '' } },
    exists: async (p) => { try { return await $.fs.exists(p) } catch { return false } },
    read: async (p) => {
      try { if (!(await $.fs.exists(p))) return null; const t = await $.fs.read(p); return typeof t === 'string' ? t : null } catch { return null }
    },
    git: async (args, cwd) => {
      try { const r = await $.process.run(['git', '--no-optional-locks', ...args], { cwd, timeoutMs: 5000 }); return r.exitCode === 0 ? r.stdout.trim() : null } catch { return null }
    },
    settings: async () => { try { return await $.settings.read({}) } catch { return {} } },
  }
}

// ---------------------------------------------------------------------------------------------------------------
// Redaction: applied to every command and script text before it is stored (never to what is matched against).
// ---------------------------------------------------------------------------------------------------------------

const SECRET_WORDS = 'token|secret|password|passwd|pwd|apikey|api_key|auth|credential|key'
const VALUE = `"[^"]*"|'[^']*'|\\S+`
const RE_URL_CREDS = /(\b[a-z][a-z0-9+.-]*:\/\/)[^\s/@:]+:[^\s/@]*@/gi
const RE_BEARER = /\bBearer\s+[^\s"']+/gi
const RE_KEY_VALUE = new RegExp(`([A-Za-z0-9_.-]*(?:${SECRET_WORDS})[A-Za-z0-9_.-]*=)(?:${VALUE})`, 'gi')
const RE_FLAG_VALUE = new RegExp(`(--?[A-Za-z0-9_.-]*(?:${SECRET_WORDS})[A-Za-z0-9_.-]*\\s+)(?!-)(?:${VALUE})`, 'gi')
const RE_LONG_RUN = /[A-Za-z0-9+/=_-]{32,}/g

export function redact(text: string, cap = CAP_COMMAND): string {
  const out = text
    .replace(RE_URL_CREDS, '$1***@')
    .replace(RE_BEARER, 'Bearer ***')
    .replace(RE_KEY_VALUE, '$1***')
    .replace(RE_FLAG_VALUE, '$1***')
    // A long opaque run with a digit is a likely token; paths (leading / . ~) and plain words are kept, or the
    // evidence itself (e.g. an absolute test path) would be erased.
    .replace(RE_LONG_RUN, (m) => (/^[./~]/.test(m) || !/\d/.test(m) || !/[A-Za-z]/.test(m) ? m : '***'))
  return out.length > cap ? `${out.slice(0, cap - 1)}…` : out
}

// ---------------------------------------------------------------------------------------------------------------
// Judging a Bash call before it runs: hooks/lib/testcmd.ts (positive proof; pure). Here: the cd prefix and the cwd.
// ---------------------------------------------------------------------------------------------------------------

type Plan = {
  cwd: string
  /** Absolute cwd, for git. */
  cwdAbs: string
  /** Leading `cd <dir> &&` segments were stripped: exit 0 still proves the run, a non-zero exit may be the cd's. */
  hasCdPrefix: boolean
  judgment: Judgment
}

const isCdPrefix = (s: Segment): boolean =>
  s.tokens[0] === 'cd' && s.op === '&&' && s.env.length === 0 && (s.tokens.length === 2 || (s.tokens.length === 3 && s.tokens[1] === '--'))

async function planBash(io: Io, root: string, cwd0: string, command: string): Promise<Plan | null> {
  const parsed = parseCommand(command.trim())
  let segs = parsed.segments
  let cwdAbs = cwd0 || root
  let hasCdPrefix = false
  // Leading `cd <dir> &&` segments only move the cwd.
  while (segs.length > 1 && isCdPrefix(segs[0] as Segment)) {
    const dir = (segs[0] as Segment).tokens.at(-1) as string // `cd dir` or `cd -- dir`
    if (dir === '-' || dir.startsWith('~') || dir.includes('$')) return null // not resolvable without guessing
    cwdAbs = dir.startsWith('/') ? dir : `${cwdAbs}/${dir}`
    segs = segs.slice(1)
    hasCdPrefix = true
  }
  if (segs.length === 0) return null
  const rel = relToRoot(root, cwdAbs)
  const cwdRel = rel === null ? cwdAbs : rel
  const stateText = await readRel(io, root, STATE_REL)
  const scripts = rel === null ? null : await packageScripts(io, root, cwdRel)
  const judgment = judge(segs, parsed.isComplex, { scripts, declared: stateText === null ? [] : declaredCommands(stateText) })
  if (judgment === null) return null
  return { cwd: cwdRel === '' ? '.' : cwdRel, cwdAbs, hasCdPrefix, judgment }
}

// ---------------------------------------------------------------------------------------------------------------
// Reading the outcome
// ---------------------------------------------------------------------------------------------------------------

type Outcome = { result: FwTestRun['result']; exitCode: number | null; reason?: string }

type BashResultFields = { interrupted?: boolean; backgroundTaskId?: string; timedOutAfterMs?: number; gitOperation?: { commit?: { sha: string; kind: string } } }

/** What the tool observably did: its exit code when it completed in the foreground, else why there is none. */
export function observe(res: { isError?: boolean; result?: unknown; text?: string }, isBackground: boolean): { exitCode: number | null; reason?: string } {
  if (res.isError === true) {
    const text = typeof res.text === 'string' ? res.text : typeof res.result === 'string' ? res.result : ''
    const m = /^Exit code (\d+)/.exec(text)
    return m ? { exitCode: Number(m[1]) } : { exitCode: null, reason: 'no-exit-code' }
  }
  const r = res.result
  if (r === undefined || r === null || typeof r !== 'object') return { exitCode: null, reason: 'no-result' }
  const b = r as BashResultFields
  if (isBackground || b.backgroundTaskId) return { exitCode: null, reason: 'background' }
  if (b.interrupted === true) return { exitCode: null, reason: 'interrupted' }
  if (b.timedOutAfterMs !== undefined) return { exitCode: null, reason: 'timeout' }
  return { exitCode: 0 }
}

/**
 * pass/fail only for a proven judgment with an observed exit code; everything else is unknown with its reason, and
 * keeps whatever exit code was observed so the reader can weigh it.
 */
export function outcomeOf(j: Judgment, seen: { exitCode: number | null; reason?: string }, hasCdPrefix: boolean): Outcome {
  if (seen.exitCode === null) return { result: 'unknown', exitCode: null, reason: seen.reason ?? 'no-exit-code' }
  if (!j.isProven) return { result: 'unknown', exitCode: seen.exitCode, reason: j.reason ?? 'unproven' }
  if (seen.exitCode === 0) return { result: 'pass', exitCode: 0 }
  if (hasCdPrefix) return { result: 'unknown', exitCode: seen.exitCode, reason: 'cd-prefix' }
  return { result: 'fail', exitCode: seen.exitCode }
}

// ---------------------------------------------------------------------------------------------------------------
// The log
// ---------------------------------------------------------------------------------------------------------------

const freshLog = (sessionId: string, now: number): FwFlightLog => ({ sessionId, startedAt: now, files: [], shellFiles: [], tests: [], commits: [], dropped: 0 })

/** Applies `change` to this session's log (a log of another session id is replaced: that is the /clear behaviour). */
async function record($: EngineInterface, io: Io, change: (log: FwFlightLog) => void): Promise<void> {
  // Same install test as every feature: no .flightwake/STATE.md under the root → this folder is not ours, keep nothing.
  if ((await fwContext(io)) === null) return
  const sid = await io.sessionId()
  const now = await $.clock.now()
  await update($, flightLog, (cur) => {
    const base = cur !== null && cur.sessionId === sid ? cur : freshLog(sid, now)
    const log: FwFlightLog = { ...base, files: [...base.files], shellFiles: [...(base.shellFiles ?? [])], tests: [...base.tests], commits: [...base.commits] }
    change(log)
    return log
  })
}

function touchFile(log: FwFlightLog, path: string, tool: string, at: number, agentId: string | undefined): void {
  const i = log.files.findIndex((f) => f.path === path)
  if (i >= 0) log.files.splice(i, 1)
  else if (log.files.length >= CAP_FILES) {
    log.dropped += 1
    return
  }
  log.files.push(agentId === undefined ? { path, tool, at } : { path, tool, at, agentId })
}

function touchShellFile(log: FwFlightLog, w: FwShellWrite): void {
  const list = log.shellFiles ?? (log.shellFiles = [])
  const i = list.findIndex((f) => f.path === w.path)
  if (i >= 0) list.splice(i, 1)
  else if (list.length >= CAP_FILES) {
    log.dropped += 1
    return
  }
  list.push(w)
}

/**
 * Candidate files a Bash command wrote, from its words (lib/shell shellWriteTargets), as repo-relative paths. A record
 * would rather miss than misrecord (unlike F4's hints, which would rather over-warn): a relative word is resolved only
 * while the cwd is certain (start, or a leading `cd X &&` chain), and paths outside the repo are dropped. The caller
 * then keeps only what git confirms as changed.
 */
function shellCandidates(root: string, cwd0: string, command: string): Array<{ path: string; via: string }> {
  const out: Array<{ path: string; via: string }> = []
  for (const w of shellWriteTargets(command)) {
    let abs: string
    if (w.path.startsWith('/')) abs = w.path
    else if (w.dir === null) continue // the shell may be anywhere by now: don't guess
    else abs = w.dir.startsWith('/') ? `${w.dir}/${w.path}` : `${cwd0 || root}/${w.dir ? `${w.dir}/` : ''}${w.path}`
    const rel = relToRoot(root, abs)
    if (rel !== null && rel !== '' && !rel.startsWith('.git/') && !out.some((o) => o.path === rel)) out.push({ path: rel, via: w.via })
  }
  return out
}

/**
 * The candidates git reports as changed after the command — modified, added, untracked or deleted (a removal only
 * shows for a tracked file, which is the point). Read-only (--no-optional-locks via io.git; --literal-pathspecs so a
 * path is never a pattern). Not a repo, git failing, or a candidate git does not list → left out.
 */
async function confirmedByGit(io: Io, root: string, candidates: Array<{ path: string; via: string }>): Promise<Array<{ path: string; via: string }>> {
  if (candidates.length === 0) return []
  const out = await io.git(['--literal-pathspecs', 'status', '--porcelain', '-z', '--untracked-files=all', '--', ...candidates.map((c) => c.path)], root)
  if (out === null) return []
  const changed = new Set<string>()
  const parts = out.split('\0')
  for (let i = 0; i < parts.length; i++) {
    // `XY path`; io.git trims the output, so the first entry may have lost the leading space of its status
    const m = /^([ MADRCUT?!]{1,2}) (.+)$/.exec(parts[i] as string)
    if (!m) continue
    changed.add(m[2] as string)
    if (/[RC]/.test((m[1] as string)[0] as string)) { const from = parts[++i]; if (from) changed.add(from) } // rename: the source follows
  }
  return candidates.filter((c) => changed.has(c.path))
}

/** The one-per-session note for a test run that was chained with other commands (its own exit code is not visible). */
const chainHint = (lang: Lang): string => M(lang, {
  en: 'flightwake: this test command ran chained with other commands, so only the whole chain\'s exit code was visible and the run cannot count as passing evidence. When you need evidence (for fw-record\'s tests:), run the test command on its own once.',
  'zh-TW': 'flightwake:這次的測試是和其他指令串在一起跑的,只看得到整串的退出碼,無法當成通過的證據。需要留證據(fw-record 的 tests:)時,請把測試指令單獨執行一次。',
  'zh-CN': 'flightwake:这次的测试是和其他命令串在一起跑的,只看得到整串的退出码,无法当成通过的证据。需要留证据(fw-record 的 tests:)时,请把测试命令单独执行一次。',
  ja: 'flightwake:このテストは他のコマンドとつなげて実行されたため、見えるのはつなげた全体の終了コードだけで、成功の証拠になりません。証拠が必要なとき(fw-record の tests:)は、テストコマンドを単独で一度実行してください。',
})

