/**
 * /fw-mod — what each of the five features is doing right now and why (2026-10-05 field feedback: the mod is
 * designed not to interrupt, so after installing nobody could tell whether it had loaded or which features were
 * acting). Read-only: it reads what the features themselves read (STATE, TRAPS, the instruction-file markers and the
 * seat block, settings) and the features' own $.state values; it changes nothing. Registered regardless of the five
 * switches — it is how you see them — but only in a folder where flightwake is installed.
 */
import type { EngineInterface, On } from 'claude-code'

import type { FwFlightLog, FwRoleGuard, FwStateSnapshot } from '../../types'
import { detectProfile, fwContext, isUninitializedState, legacyStatuslineActive, M, MOD_VERSION, readRel, STATE_REL, TRAPS_REL } from '../lib/core'
import type { Io, Lang } from '../lib/core'
import { parseSeatBlock } from '../lib/roles'
import { hasMatchers, isActive, parseTraps } from '../lib/traps'

export type Switches = { stateInject: boolean; band: boolean; recorder: boolean; tripwire: boolean; roleGuard: boolean }

// The Io closure over this file's `$` (IO_OF_TEMPLATE in hooks/lib/core.ts; `$` may not cross an import).
function ioOf($: EngineInterface): Io {
  return {
    root: async () => { try { return (await $.session.root()).replace(/\/+$/, '') } catch { return '' } },
    sessionId: async () => { try { return await $.session.id() } catch { return '' } },
    exists: async (p) => { try { return await $.fs.exists(p) } catch { return false } },
    read: async (p) => {
      try { if (!(await $.fs.exists(p))) return null; const t = await $.fs.read(p); return typeof t === 'string' ? t : null } catch { return null }
    },
    git: async (args, cwd) => {
      try { const r = await $.process.run(['git', '--no-optional-locks', ...args], { cwd, timeoutMs: 5000 }); return r.exitCode === 0 ? r.stdout.trim() : null } catch { return null }
    },
    settings: async () => { try { return await $.settings.read({}) } catch { return {} } },
  }
}

const SEAT_FILES = ['.claude/CLAUDE.md', 'CLAUDE.md'] as const
// The loader holds every $.state reference to literal plugin/key values written in this file
const SNAPSHOT_REF = { plugin: 'flightwake-mod', key: 'stateSnapshot' } as const
const LOG_REF = { plugin: 'flightwake-mod', key: 'flightLog' } as const
const GUARD_REF = { plugin: 'flightwake-mod', key: 'roleGuard' } as const

/** How to switch a feature on or off yourself (plugin options are not read from project settings). */
const howTo = (lang: Lang, key: keyof Switches, value: boolean): string => {
  const json = `"pluginConfigs": { "flightwake-mod@skills-dir": { "options": { "${key}": ${value} } } }`
  return M(lang, {
    en: `turn it ${value ? 'on' : 'off'} in /config, or in your user settings (~/.claude/settings.json): ${json}`,
    'zh-TW': `在 /config ${value ? '開啟' : '關閉'},或寫進你的使用者設定(~/.claude/settings.json):${json}`,
    'zh-CN': `在 /config ${value ? '开启' : '关闭'},或写进你的用户设置(~/.claude/settings.json):${json}`,
    ja: `/config で${value ? 'オン' : 'オフ'}にするか、ユーザー設定(~/.claude/settings.json)に:${json}`,
  })
}
const ON = (lang: Lang) => M(lang, { en: 'on', 'zh-TW': '開啟', 'zh-CN': '开启', ja: 'オン' })
const OFF = (lang: Lang) => M(lang, { en: 'off', 'zh-TW': '關閉', 'zh-CN': '关闭', ja: 'オフ' })
const IDLE = (lang: Lang) => M(lang, { en: 'idle', 'zh-TW': '閒置', 'zh-CN': '闲置', ja: '待機' })

const LABEL: Record<keyof Switches, Record<Lang, string>> = {
  stateInject: { en: 'STATE at session start', 'zh-TW': 'STATE 自動載入', 'zh-CN': 'STATE 自动载入', ja: 'STATE の自動読み込み' },
  band: { en: 'band above the prompt', 'zh-TW': '輸入框上方橫條', 'zh-CN': '输入框上方横条', ja: '入力欄上の帯' },
  recorder: { en: 'session flight log', 'zh-TW': 'session 行車記錄', 'zh-CN': 'session 行车记录', ja: 'セッション記録' },
  tripwire: { en: 'trap tripwire', 'zh-TW': '踩坑絆線', 'zh-CN': '踩坑绊线', ja: '落とし穴の検知線' },
  roleGuard: { en: 'role guard', 'zh-TW': '角色守門', 'zh-CN': '角色守门', ja: 'ロールガード' },
}
const line = (lang: Lang, key: keyof Switches, state: string, why: string): string => `- **${LABEL[key][lang]}** (\`${key}\`): ${state} — ${why}`

async function statusText($: EngineInterface, sw: Switches): Promise<string | null> {
  const io = ioOf($)
  const ctx = await fwContext(io)
  if (ctx === null) return null
  const { root, lang } = ctx
  const sid = await io.sessionId()
  const state = await readRel(io, root, STATE_REL)
  const out: string[] = []
  out.push(`## flightwake-mod v${MOD_VERSION}`, '')
  out.push(M(lang, {
    en: `language: ${lang} · profile: ${await detectProfile(io, root)} · root: ${root}`,
    'zh-TW': `語言(language): ${lang} · 類型(profile): ${await detectProfile(io, root)} · 根目錄: ${root}`,
    'zh-CN': `语言(language): ${lang} · 类型(profile): ${await detectProfile(io, root)} · 根目录: ${root}`,
    ja: `言語(language): ${lang} · 種別(profile): ${await detectProfile(io, root)} · ルート: ${root}`,
  }), '')

  // F1
  if (!sw.stateInject) out.push(line(lang, 'stateInject', OFF(lang), howTo(lang, 'stateInject', true)))
  else {
    let snap: FwStateSnapshot | null = null
    try { snap = (await $.state.get(SNAPSHOT_REF)).value ?? null } catch {}
    const isThisSession = snap !== null && snap.sessionId === sid && snap.text !== null
    out.push(line(lang, 'stateInject', ON(lang), state !== null && isUninitializedState(state)
      ? M(lang, { en: 'STATE is not initialized yet, so only a "run /fw-coldstart" note is injected', 'zh-TW': 'STATE 尚未初始化,所以只注入「請先跑 /fw-coldstart」的提示', 'zh-CN': 'STATE 尚未初始化,所以只注入「请先跑 /fw-coldstart」的提示', ja: 'STATE が未初期化のため「まず /fw-coldstart」という注記だけを注入' })
      : isThisSession
        ? M(lang, { en: 'STATE was injected into this session (a snapshot taken at session start)', 'zh-TW': '已在本 session 注入 STATE(session 開始時取的快照)', 'zh-CN': '已在本 session 注入 STATE(session 开始时取的快照)', ja: 'このセッションに STATE を注入済み(セッション開始時のスナップショット)' })
        : M(lang, { en: 'nothing injected yet in this session (it is taken when a session starts)', 'zh-TW': '本 session 尚未注入(在 session 開始時取得)', 'zh-CN': '本 session 尚未注入(在 session 开始时取得)', ja: 'このセッションではまだ注入していない(セッション開始時に取得)' })))
  }

  // F2
  if (!sw.band) out.push(line(lang, 'band', OFF(lang), howTo(lang, 'band', true)))
  else out.push(line(lang, 'band', ON(lang), (await legacyStatuslineActive(io))
    ? M(lang, { en: 'hiding the fields the bottom gauge already shows (health / STATE lag / context); only the one-time 80% context toast remains', 'zh-TW': '偵測到底部儀表,隱藏儀表已顯示的欄位(health/STATE 落後/context),只保留 context 80% 時的一次提示', 'zh-CN': '检测到底部仪表,隐藏仪表已显示的栏位(health/STATE 落后/context),只保留 context 80% 时的一次提示', ja: '下部ゲージを検出したため、ゲージが表示する欄(health / STATE の遅れ / context)を隠し、context 80% の一度きりのトーストだけ残す' })
    : M(lang, { en: 'shown above the prompt with health, STATE lag and context use (it stands in for the bottom gauge)', 'zh-TW': '顯示在輸入框上方:health、STATE 落後、context 用量(代替底部儀表)', 'zh-CN': '显示在输入框上方:health、STATE 落后、context 用量(代替底部仪表)', ja: '入力欄の上に health・STATE の遅れ・context 使用量を表示(下部ゲージの代わり)' })))

  // F3
  if (!sw.recorder) out.push(line(lang, 'recorder', OFF(lang), howTo(lang, 'recorder', true)))
  else {
    let raw: FwFlightLog | null = null
    try { raw = (await $.state.get(LOG_REF)).value ?? null } catch {}
    const log = raw !== null && raw.sessionId === sid ? raw : null
    const n = { files: log?.files.length ?? 0, shell: log?.shellFiles?.length ?? 0, tests: log?.tests.length ?? 0, commits: log?.commits.length ?? 0 }
    out.push(line(lang, 'recorder', ON(lang), M(lang, {
      en: `this session: ${n.files} file(s) by tools, ${n.shell} via shell (inferred), ${n.tests} test run(s), ${n.commits} commit(s) — /fw-log prints them`,
      'zh-TW': `本 session:工具改了 ${n.files} 個檔、shell 推斷 ${n.shell} 個、測試 ${n.tests} 次、commit ${n.commits} 個 — /fw-log 印出明細`,
      'zh-CN': `本 session:工具改了 ${n.files} 个文件、shell 推断 ${n.shell} 个、测试 ${n.tests} 次、commit ${n.commits} 个 — /fw-log 打印明细`,
      ja: `このセッション:ツールで ${n.files} 件、シェル推定 ${n.shell} 件、テスト ${n.tests} 回、commit ${n.commits} 件 — /fw-log で詳細`,
    })))
  }

  // F4
  if (!sw.tripwire) out.push(line(lang, 'tripwire', OFF(lang), howTo(lang, 'tripwire', true)))
  else {
    const traps = await readRel(io, root, TRAPS_REL)
    const watched = traps === null ? 0 : parseTraps(traps).filter((t) => isActive(t) && hasMatchers(t)).length
    out.push(watched === 0
      ? line(lang, 'tripwire', IDLE(lang), M(lang, { en: 'no active TRAPS entry has paths or commands — add them to an entry to be warned (fw-trap explains the two fields)', 'zh-TW': 'TRAPS 裡沒有任何帶 paths 或 commands 的 active 條目 — 在條目加上這兩個欄位才會提示(fw-trap 有說明)', 'zh-CN': 'TRAPS 里没有任何带 paths 或 commands 的 active 条目 — 在条目加上这两个栏位才会提示(fw-trap 有说明)', ja: 'TRAPS に paths か commands を持つ active な項目がない — 項目にこの 2 欄を足すとヒントが出る(fw-trap に説明あり)' }))
      : line(lang, 'tripwire', ON(lang), M(lang, { en: `watching ${watched} TRAPS entr${watched === 1 ? 'y' : 'ies'} with paths / commands`, 'zh-TW': `監看 ${watched} 條帶 paths / commands 的 TRAPS 條目`, 'zh-CN': `监看 ${watched} 条带 paths / commands 的 TRAPS 条目`, ja: `paths / commands を持つ TRAPS 項目 ${watched} 件を監視中` })))
  }

  // F5
  const notBoundary = M(lang, { en: 'not a security boundary', 'zh-TW': '不是安全邊界', 'zh-CN': '不是安全边界', ja: 'セキュリティ境界ではない' })
  if (!sw.roleGuard) out.push(line(lang, 'roleGuard', OFF(lang), `${M(lang, { en: 'opt-in', 'zh-TW': '選配', 'zh-CN': '选配', ja: 'オプトイン' })}; ${howTo(lang, 'roleGuard', true)} (${notBoundary})`))
  else {
    let snap: FwRoleGuard | null = null
    try { snap = (await $.state.get(GUARD_REF)).value ?? null } catch {}
    let role: string | null = null
    let deny: string[] = []
    let source = 'seat'
    let released: string[] = []
    if (snap !== null && snap.sessionId === sid && snap.root === root) {
      role = snap.role; deny = snap.denyWrite; source = snap.source; released = snap.isAllReleased ? ['*all*'] : snap.released
    } else {
      for (const rel of SEAT_FILES) {
        const t = await readRel(io, root, rel)
        const seat = t === null ? null : parseSeatBlock(t)
        if (seat) { role = seat.id; deny = seat.denyWrite; break }
      }
    }
    if (role === null) out.push(line(lang, 'roleGuard', IDLE(lang), M(lang, { en: "this folder's Claude seat has no role (roles apply writes one into CLAUDE.md)", 'zh-TW': '這個資料夾的 Claude 座位沒有角色(roles apply 會寫進 CLAUDE.md)', 'zh-CN': '这个文件夹的 Claude 座位没有角色(roles apply 会写进 CLAUDE.md)', ja: 'このフォルダーの Claude の席にロールがない(roles apply が CLAUDE.md に書く)' })))
    else if (deny.length === 0) out.push(line(lang, 'roleGuard', IDLE(lang), M(lang, { en: `role ${role} has no deny-write line, so there is nothing to guard`, 'zh-TW': `角色 ${role} 沒有 deny-write,沒有要守的路徑`, 'zh-CN': `角色 ${role} 没有 deny-write,没有要守的路径`, ja: `ロール ${role} に deny-write がなく、守る対象がない` })))
    else out.push(line(lang, 'roleGuard', ON(lang), M(lang, {
      en: `role ${role} (${source}) blocks Edit/Write into ${deny.join(', ')}${released.length ? `; released this session: ${released.join(', ')}` : ''} (${notBoundary})`,
      'zh-TW': `角色 ${role}(${source})擋下 Edit/Write 寫入 ${deny.join(', ')}${released.length ? `;本 session 已放行:${released.join(', ')}` : ''}(${notBoundary})`,
      'zh-CN': `角色 ${role}(${source})挡下 Edit/Write 写入 ${deny.join(', ')}${released.length ? `;本 session 已放行:${released.join(', ')}` : ''}(${notBoundary})`,
      ja: `ロール ${role}(${source})が ${deny.join(', ')} への Edit/Write を止める${released.length ? `。このセッションで解除:${released.join(', ')}` : ''}(${notBoundary})`,
    })))
  }
  out.push('', M(lang, { en: 'Read-only: /fw-mod changes nothing.', 'zh-TW': '唯讀:/fw-mod 不改任何東西。', 'zh-CN': '只读:/fw-mod 不改任何东西。', ja: '読み取り専用:/fw-mod は何も変更しない。' }))
  return out.join('\n')
}

let isCommandRegistered = false
async function ensureCommand($: EngineInterface): Promise<void> {
  if (isCommandRegistered) return
  isCommandRegistered = true
  try {
    const ctx = await fwContext(ioOf($))
    if (ctx === null) { isCommandRegistered = false; return }
    await $.command.register({
      name: 'fw-mod',
      description: M(ctx.lang, {
        en: 'Show what each flightwake-mod feature is doing and why (read-only)',
        'zh-TW': '列出 flightwake-mod 各功能的狀態與原因(唯讀)',
        'zh-CN': '列出 flightwake-mod 各功能的状态与原因(只读)',
        ja: 'flightwake-mod の各機能の状態と理由を表示(読み取り専用)',
      }),
    })
  } catch {
    isCommandRegistered = false
  }
}

export function registerStatus(on: On, switches: Switches): void {
  on('session.start', {}, async ($, e, next) => {
    await ensureCommand($)
    return next(e)
  })
  on('command.run', { command: 'fw-mod' }, async ($, e, next) => {
    try {
      const text = await statusText($, switches)
      return text === null ? next(e) : { text }
    } catch {
      return next(e)
    }
  })
}

files.hooks/lib/core.ts:
/**
 * Shared world access for every feature.
 *
 * READ SCOPE (docs/plans/mods.md, revised 2026-10-05) — the mod reads only:
 *   .flightwake/ · git state · the flightwake / roles markers in CLAUDE.md, .claude/CLAUDE.md, CLAUDE.local.md ·
 *   the flightwake marker in AGENTS.md / GEMINI.md (language only) · package.json `scripts` · the effective
 *   `statusLine` setting. Nothing else, and no network. Everything outside the module goes through `$`; every helper here
 * swallows its own errors and answers null/false, so a feature built on them degrades silently (no
 * .flightwake/, not a git repo, git missing, unreadable file) instead of surfacing an error to the person.
 * Read-only by contract: nothing here writes outside the mod's own $.state / $.store.
 */

export const PLUGIN = 'flightwake-mod' as const
/** Mirrors .claude-plugin/plugin.json `version` (the mod cannot read its own manifest); test/smoke.sh checks they match. */
export const MOD_VERSION = '0.1.0'
export const FW_DIR = '.flightwake'
export const STATE_REL = '.flightwake/STATE.md'
export const TRAPS_REL = '.flightwake/TRAPS.md'

export type Lang = 'en' | 'zh-TW' | 'zh-CN' | 'ja'
export const LANGS: readonly Lang[] = ['en', 'zh-TW', 'zh-CN', 'ja']
/** A message in the four install languages; a missing key falls back to English (same rule as hooks/*.mjs). */
export type Msg = { en: string } & Partial<Record<Exclude<Lang, 'en'>, string>>
export const M = (lang: Lang, m: Msg): string => m[lang] ?? m.en

/** One markdown table cell: newlines become spaces, then `\` before `|` is escaped so a `\|` in the text stays unambiguous. */
export const tableCell = (s: string): string => s.replace(/\r?\n/g, ' ').replace(/\\/g, '\\\\').replace(/\|/g, '\\|')

/**
 * The world as the shared helpers see it. `$` can't be passed across an import — the engine's loader refuses a
 * module that does (`$ is followed only into a function declared in this same file, never across an import`) —
 * so each feature file builds this from its own `$` with a local `ioOf($)` (copy IO_OF_TEMPLATE below) and passes
 * the closures in. Every member must swallow its own errors (null / false / {}), never throw.
 */
export type Io = {
  /** $.session.root(), absolute, no trailing slash; '' when unreadable. */
  root: () => Promise<string>
  /** $.session.id(); '' when unreadable. */
  sessionId: () => Promise<string>
  /** $.fs.exists(abs); false on error. */
  exists: (abs: string) => Promise<boolean>
  /** $.fs.read(abs) as text; null when absent/unreadable. */
  read: (abs: string) => Promise<string | null>
  /**
   * `git --no-optional-locks <args>` in cwd: trimmed stdout on exit 0, null otherwise (not a repo, git missing,
   * timeout). The flag is part of the zero-write promise: a plain `git status` may refresh and rewrite .git/index.
   */
  git: (args: readonly string[], cwd: string) => Promise<string | null>
  /** $.settings.read({}) — the merged, effective settings; {} on error. */
  settings: () => Promise<Record<string, unknown>>
}

/*
 * IO_OF_TEMPLATE — paste into a feature file (it must live in the same file as the hooks that call it):
 *
 *   import type { EngineInterface } from 'claude-code'
 *   import type { Io } from '../lib/core'
 *
 *   function ioOf($: EngineInterface): Io {
 *     return {
 *       root: async () => { try { return (await $.session.root()).replace(/\/+$/, '') } catch { return '' } },
 *       sessionId: async () => { try { return await $.session.id() } catch { return '' } },
 *       exists: async (p) => { try { return await $.fs.exists(p) } catch { return false } },
 *       read: async (p) => {
 *         try { if (!(await $.fs.exists(p))) return null; const t = await $.fs.read(p); return typeof t === 'string' ? t : null } catch { return null }
 *       },
 *       git: async (args, cwd) => {
 *         try { const r = await $.process.run(['git', '--no-optional-locks', ...args], { cwd, timeoutMs: 5000 }); return r.exitCode === 0 ? r.stdout.trim() : null } catch { return null }
 *       },
 *       settings: async () => { try { return await $.settings.read({}) } catch { return {} } },
 *     }
 *   }
 */


export const joinPath = (root: string, rel: string): string => `${root}/${rel.replace(/^\/+/, '')}`

/**
 * `abs` relative to `root` with forward slashes, or null when it lies outside root.
 * Purely lexical: collapses `.`/`..` segments; does not resolve links.
 */
export function relToRoot(root: string, abs: string): string | null {
  const norm = (p: string) => {
    const out: string[] = []
    for (const seg of p.split('/')) {
      if (seg === '' || seg === '.') continue
      if (seg === '..') out.pop()
      else out.push(seg)
    }
    return out
  }
  const r = norm(root)
  const a = norm(abs.startsWith('/') ? abs : `${root}/${abs}`)
  if (a.length < r.length || r.some((s, i) => a[i] !== s)) return null
  return a.slice(r.length).join('/')
}

/** A text file under the root, or null when absent/unreadable. */
export const readRel = (io: Io, root: string, rel: string): Promise<string | null> => io.read(joinPath(root, rel))

/** `git <args>` in root (see Io.git). */
export const git = (io: Io, root: string, args: readonly string[]): Promise<string | null> => io.git(args, root)

/** The YAML-ish frontmatter block of a Markdown file as flat key → raw string (inline comments stripped). */
export function parseFrontmatter(text: string): Record<string, string> | null {
  const m = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text)
  if (!m || m[1] === undefined) return null
  return parseFlatYaml(m[1])
}

/** `key: value` lines → record; `# comment` tails and surrounding quotes removed; nested/continuation lines ignored. */
export function parseFlatYaml(block: string): Record<string, string> {
  const out: Record<string, string> = {}
  for (const line of block.split(/\r?\n/)) {
    const m = /^([A-Za-z_][\w-]*):\s*(.*)$/.exec(line)
    if (!m || m[1] === undefined) continue
    let v = (m[2] ?? '').replace(/\s+#.*$/, '').trim()
    if (/^(['"]).*\1$/.test(v)) v = v.slice(1, -1)
    out[m[1]] = v
  }
  return out
}

/** An inline YAML list (`[a, "b c", 'd']`) or a single scalar → items; empty input → []. */
export function parseInlineList(v: string | undefined): string[] {
  if (!v) return []
  const s = v.trim()
  const body = s.startsWith('[') && s.endsWith(']') ? s.slice(1, -1) : s
  const items: string[] = []
  const re = /\s*("([^"\\]*(?:\\.[^"\\]*)*)"|'([^']*)'|([^,]+))\s*(?:,|$)/g
  let m: RegExpExecArray | null
  while ((m = re.exec(body)) !== null && m[0] !== '') {
    const item = (m[2] ?? m[3] ?? m[4] ?? '').trim()
    if (item) items.push(item)
  }
  return items
}

/**
 * Files whose flightwake marker carries the install language, in bin/cli.mjs detectMarker order: Claude's first,
 * then AGENTS.md / GEMINI.md (read for the marker only — a repo installed for Codex/Gemini alone has just those).
 */
export const MARKER_FILES = ['.claude/CLAUDE.md', 'CLAUDE.md', 'CLAUDE.local.md', 'AGENTS.md', 'GEMINI.md'] as const
/** `<!-- flightwake:begin v<version> [attr=value …] -->`; attributes in any order (e.g. `lang=zh-TW profile=notes`). */
const MARKER_RE = /<!-- flightwake:begin v(\d+\.\d+\.\d+\S*)((?:\s+[\w-]+=[^\s>]+)*)\s*-->/

/** The language attribute of a marker line, or what its absence means; null when the text holds no marker. */
export function markerLang(text: string): Lang | null {
  const m = MARKER_RE.exec(text)
  if (!m) return null
  const attrs = m[2] ?? ''
  const lang = /(?:^|\s)lang=([\w-]+)/.exec(attrs)?.[1]
  // A pre-0.9 marker carried no attributes at all, and every install back then was zh-TW. A marker that has other
  // attributes but no lang is a newer writer that left the language out: fall back to the default, English.
  if (lang === undefined) return attrs.trim() === '' ? 'zh-TW' : 'en'
  return (LANGS as readonly string[]).includes(lang) ? (lang as Lang) : 'en'
}

/** The profile attribute of a marker (`profile=notes`); absent = code; null when the text holds no marker. */
export function markerProfile(text: string): 'code' | 'notes' | null {
  const m = MARKER_RE.exec(text)
  if (!m) return null
  return /(?:^|\s)profile=notes(?:\s|$)/.test(m[2] ?? '') ? 'notes' : 'code'
}

/** The profile recorded at install time, from the same first marker detectLang reads; none → code. */
export async function detectProfile(io: Io, root: string): Promise<'code' | 'notes'> {
  for (const rel of MARKER_FILES) {
    const t = await readRel(io, root, rel)
    if (t === null) continue
    const p = markerProfile(t)
    if (p !== null) return p
  }
  return 'code'
}

/** The language recorded at install time: the first marker found in MARKER_FILES; none → en. */
export async function detectLang(io: Io, root: string): Promise<Lang> {
  for (const rel of MARKER_FILES) {
    const t = await readRel(io, root, rel)
    if (t === null) continue
    const l = markerLang(t)
    if (l !== null) return l
  }
  return 'en'
}

export type Health = 'green' | 'yellow' | 'red' | 'unknown'

/** health from STATE frontmatter (`health: green  # …`); anything unrecognised is 'unknown'. */
export function healthOf(stateText: string): Health {
  const h = /^health:\s*(\S+)/m.exec(stateText)?.[1]
  return h === 'green' || h === 'yellow' || h === 'red' ? h : 'unknown'
}

/** The shipped STATE template's own frontmatter placeholders (identical in all four languages). */
const TEMPLATE_FIELDS = ['{{DATE}}', '{{SESSION_OR_PERSON}}', '{{YYMMDD}}', '{{slug}}'] as const

/**
 * STATE is still the unfilled template: its frontmatter still holds one of the template's own placeholders.
 * Only those count — a filled STATE may legitimately document `{{customer}}`-style placeholders in its body.
 */
export function isUninitializedState(stateText: string): boolean {
  const m = /^---\r?\n([\s\S]*?)\r?\n---/.exec(stateText)
  if (!m || m[1] === undefined) return false
  const front = m[1]
  return TEMPLATE_FIELDS.some((f) => front.includes(f))
}

/**
 * STATE lag with state-check.mjs's full semantics:
 * - `dirty`: STATE.md has uncommitted changes → an update is in progress, counts as fresh
 * - `no-baseline`: STATE.md was never committed → not measured (state-check stays quiet)
 * - `behind`: human commits since STATE's last commit (`--author=\[bot\]` excluded); 0 = in sync
 * - `error`: a git call failed midway → unknown; callers must NEVER render this as "in sync"
 * null: not a git repo / git unavailable (nothing to say).
 */
export type StateLag =
  | { kind: 'dirty' }
  | { kind: 'no-baseline' }
  | { kind: 'behind'; behind: number }
  | { kind: 'error' }

export async function stateLag(io: Io, root: string): Promise<StateLag | null> {
  const status = await git(io, root, ['status', '--porcelain', '--', STATE_REL])
  if (status === null) return null
  if (status !== '') return { kind: 'dirty' }
  const last = await git(io, root, ['log', '-1', '--format=%H', '--', STATE_REL])
  if (last === null) return { kind: 'error' }
  if (last === '') return { kind: 'no-baseline' }
  const range = `${last}..HEAD`
  const all = await git(io, root, ['rev-list', '--count', range])
  const bots = await git(io, root, ['rev-list', '--count', '--author=\\[bot\\]', range])
  const a = Number(all)
  const b = Number(bots)
  if (all === null || bots === null || all === '' || bots === '' || !Number.isFinite(a) || !Number.isFinite(b)) {
    return { kind: 'error' }
  }
  return { kind: 'behind', behind: Math.max(0, a - b) }
}

/**
 * Whether the legacy node gauge (hooks/statusline.mjs) is the *effective* statusLine: the settings as the engine
 * runs under them (every source merged), not whether a settings file mentions it. The mod only reads this to
 * hide its own duplicate fields; it never edits settings.
 */
export async function legacyStatuslineActive(io: Io): Promise<boolean> {
  try {
    return JSON.stringify((await io.settings()).statusLine ?? null).includes('statusline.mjs')
  } catch {
    return false
  }
}

/**
 * `scripts` of the package.json in `dirRel` (repo-relative, '' = root), or null when there is none / it doesn't
 * parse. The only reason the mod reads package.json: confirming what a `npm test`-style script actually runs.
 */
export async function packageScripts(io: Io, root: string, dirRel = ''): Promise<Record<string, string> | null> {
  const t = await readRel(io, root, dirRel ? `${dirRel.replace(/\/+$/, '')}/package.json` : 'package.json')
  if (t === null) return null
  try {
    const s = JSON.parse(t).scripts
    if (!s || typeof s !== 'object') return null
    const out: Record<string, string> = {}
    for (const [k, v] of Object.entries(s)) if (typeof v === 'string') out[k] = v
    return out
  } catch {
    return null
  }
}

/** FNV-1a 32-bit, hex — a cheap content version for dedup keys (not a security hash). */
export function contentHash(text: string): string {
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h.toString(16).padStart(8, '0')
}

/**
 * The context every feature starts from: the root and the install language, or null when this folder has no
 * .flightwake/STATE.md (flightwake isn't installed here → every feature stays silent).
 */
export type FwContext = { root: string; lang: Lang }
export async function fwContext(io: Io): Promise<FwContext | null> {
  const root = (await io.root()).replace(/\/+$/, '')
  if (!root) return null
  if (!(await io.exists(joinPath(root, STATE_REL)))) return null
  return { root, lang: await detectLang(io, root) }
}

files.hooks/lib/shell.ts:
/**
 * A deliberately small shell-command reader for F3 (test recognition) and F4 (command tripwires).
 * It is NOT a shell parser: it splits on top-level control operators outside quotes and tokenizes each simple
 * command. Anything it can't read plainly is flagged (`isComplex`) so callers can stay conservative.
 */

export type Segment = {
  /** Words of one simple command, quotes removed; leading `VAR=value` assignments moved to `env`. */
  tokens: string[]
  env: string[]
  /** The operator that ended this segment: '&&', '||', ';', '|', '&', '\n', or '' for the last one. */
  op: string
  /** A subshell boundary marker (`(` / `)`), carrying no words; F4 walks into subshells, F3 counts it as compound. */
  group?: 'open' | 'close'
}

export type ParsedCommand = {
  segments: Segment[]
  /** Command substitution, backticks, subshell parens, heredocs or an unterminated quote — not plainly readable. */
  isComplex: boolean
}

const OPS = ['&&', '||', ';;', '|&', ';', '|', '&', '\n'] as const

export function parseCommand(command: string): ParsedCommand {
  const segments: Segment[] = []
  let isComplex = false
  let tokens: string[] = []
  let cur = ''
  let hasCur = false
  let quote: '' | "'" | '"' = ''
  const pushWord = () => {
    if (hasCur) tokens.push(cur)
    cur = ''
    hasCur = false
  }
  const endSegment = (op: string) => {
    pushWord()
    const env: string[] = []
    while (tokens.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(tokens[0] as string)) env.push(tokens.shift() as string)
    if (tokens.length || env.length) segments.push({ tokens, env, op })
    else if (segments.length && op) (segments[segments.length - 1] as Segment).op = op
    tokens = []
  }
  for (let i = 0; i < command.length; i++) {
    const c = command[i] as string
    if (quote) {
      if (c === quote) quote = ''
      else if (c === '\\' && quote === '"' && i + 1 < command.length) cur += command[++i]
      else {
        if (quote === '"' && (c === '`' || (c === '$' && command[i + 1] === '('))) isComplex = true
        cur += c
      }
      continue
    }
    if (c === "'" || c === '"') {
      quote = c
      hasCur = true
      continue
    }
    if (c === '\\' && i + 1 < command.length) {
      if (command[i + 1] === '\n') { i++; continue } // line continuation
      cur += command[++i]
      hasCur = true
      continue
    }
    // `$( … )` and backticks: command substitution stays inside the word (nested parens counted)
    if (c === '$' && command[i + 1] === '(') {
      isComplex = true
      let depth = 0
      for (; i < command.length; i++) {
        const d = command[i] as string
        cur += d
        if (d === '(') depth++
        else if (d === ')' && --depth === 0) break
      }
      hasCur = true
      continue
    }
    if (c === '`') {
      isComplex = true
      const close = command.indexOf('`', i + 1)
      const end = close < 0 ? command.length - 1 : close
      cur += command.slice(i, end + 1)
      i = end
      hasCur = true
      continue
    }
    // A bare `(` / `)` opens / closes a subshell: an explicit marker segment, so the commands inside stay visible
    if (c === '(' || c === ')') {
      isComplex = true
      endSegment('')
      segments.push({ tokens: [], env: [], op: '', group: c === '(' ? 'open' : 'close' })
      continue
    }
    if (c === '<' && command[i + 1] === '<') isComplex = true
    // `&` inside a redirection (`2>&1`, `>&2`, `<&3`, `&>file`, `&>>file`) is part of the word, not an operator
    const isRedirAmp = c === '&' && (command[i - 1] === '>' || command[i - 1] === '<' || command[i + 1] === '>')
    const op = isRedirAmp ? undefined : OPS.find((o) => command.startsWith(o, i))
    if (op) {
      endSegment(op === '|&' ? '|' : op === ';;' ? ';' : op)
      i += op.length - 1
      continue
    }
    if (c === ' ' || c === '\t') {
      pushWord()
      continue
    }
    if (c === '#' && !hasCur) {
      // a comment runs to the end of its line only; the newline itself still ends the segment
      while (i + 1 < command.length && command[i + 1] !== '\n') i++
      continue
    }
    cur += c
    hasCur = true
  }
  if (quote) isComplex = true
  endSegment('')
  return { segments, isComplex }
}

/** True when the tokens start with every token of `prefix` (whitespace-separated), compared exactly. */
export function startsWithTokens(tokens: readonly string[], prefix: string): boolean {
  const p = prefix.trim().split(/\s+/).filter(Boolean)
  return p.length > 0 && p.length <= tokens.length && p.every((t, i) => tokens[i] === t)
}

/**
 * A file a command writes or removes, as far as its words say. `dir` is where a relative `path` resolves: '' = the
 * command's starting directory, 'pkg' or '/abs' after a leading `cd … &&` chain, null = no longer certain (any other cd,
 * or a cd inside a subshell, happened earlier) — the caller must not resolve a relative path then.
 */
export type ShellWrite = {
  path: string
  via: '>' | '>>' | 'cp' | 'mv' | 'rm' | 'tee' | 'sed -i'
  /** remove = rm targets and mv sources (gone afterwards); write = everything else. */
  effect: 'write' | 'remove'
  dir: string | null
}

/** A word that can only be a path as written: no expansions, no globs, not a device, not a descriptor. */
const isPathWord = (w: string | undefined): w is string =>
  typeof w === 'string' && w !== '' && !/[$`*?[\]{}~]/.test(w) && !w.startsWith('/dev/') && !w.startsWith('&') && !w.startsWith('-')

/**
 * Splits a command's arguments by its own option grammar: flags that take a value consume it (attached or as the next
 * word), `--` ends options, everything else is an operand. `withValue` lists the short and long options that take a value.
 */
function operands(args: readonly string[], withValue: { short: string; long: readonly string[] }): { operands: string[]; values: Record<string, string[]> } {
  const out: string[] = []
  const values: Record<string, string[]> = {}
  const keep = (k: string, v: string) => { (values[k] ??= []).push(v) }
  for (let i = 0; i < args.length; i++) {
    const a = args[i] as string
    if (a === '--') { out.push(...args.slice(i + 1)); break }
    if (a.startsWith('--')) {
      const [name, eq] = a.includes('=') ? [a.slice(2, a.indexOf('=')), a.slice(a.indexOf('=') + 1)] : [a.slice(2), undefined]
      if (withValue.long.includes(name)) keep(name, eq ?? (args[++i] ?? ''))
      continue
    }
    if (a.startsWith('-') && a.length > 1) {
      // a cluster of short flags; the first one that takes a value takes the rest of the word or the next word
      for (let j = 1; j < a.length; j++) {
        const f = a[j] as string
        if (withValue.short.includes(f)) { keep(f, j + 1 < a.length ? a.slice(j + 1) : (args[++i] ?? '')); break }
      }
      continue
    }
    out.push(a)
  }
  return { operands: out, values }
}

const joinDir = (dir: string, name: string): string => `${dir.replace(/\/+$/, '')}/${name.replace(/^.*\//, '')}`

/**
 * The write targets plainly readable from a command (F3's "changed through shell commands" list): output
 * redirections (`>f`, `>> f`, `2>f`, `&>f`; not fd duplications like `2>&1`, not /dev/*), and the operands of
 * cp/mv (destination, or each source joined to `-t DIR`; mv also its sources), rm, tee and `sed -i`, each read with that
 * command's option grammar so option values (sed -e/-f scripts, -S suffixes, …) never pass for paths. Words with
 * expansions or globs are skipped. Only a candidate list — the recorder lists what git confirms as changed.
 */
export function shellWriteTargets(command: string): ShellWrite[] {
  const out: ShellWrite[] = []
  let dir: string | null = ''
  let isChainCertain = true // every segment so far ended with && (a cd here is a certain move)
  let depth = 0
  for (const seg of parseCommand(command).segments) {
    if (seg.group === 'open') { depth++; continue }
    if (seg.group === 'close') { depth = Math.max(0, depth - 1); if (seg.op && seg.op !== '&&') isChainCertain = false; continue }
    const add = (path: string, via: ShellWrite['via'], effect: ShellWrite['effect'] = 'write') => { if (isPathWord(path)) out.push({ path, via, effect, dir }) }
    const words: string[] = []
    const t = seg.tokens
    for (let i = 0; i < t.length; i++) {
      const tok = t[i] as string
      const m = /^(?:\d*|&)(>>?)(.*)$/.exec(tok)
      if (m) {
        const via = m[1] as '>' | '>>'
        const rest = m[2] as string
        if (rest === '') add(t[++i] as string, via) // `> file`
        else if (!rest.startsWith('&')) add(rest, via) // `>file`; `>&2` duplicates a descriptor
        continue
      }
      if (/^\d*<.*/.test(tok)) { if (tok.replace(/^\d*</, '') === '') i++; continue } // input redirection: skip its word
      words.push(tok)
    }
    const [cmd, ...args] = words
    if (cmd === 'cd') {
      const target = args[0] === '--' ? args[1] : args[0]
      const isResolvable = target !== undefined && args.length <= (args[0] === '--' ? 2 : 1) && target !== '-' && isPathWord(target)
      dir = depth === 0 && isChainCertain && seg.op === '&&' && isResolvable && dir !== null
        ? (target.startsWith('/') ? target : dir ? `${dir}/${target}` : target)
        : null
    } else if (cmd === 'cp' || cmd === 'mv') {
      const { operands: o, values } = operands(args, { short: 'tS', long: ['target-directory', 'suffix', 'backup'] })
      const into = values.t?.[0] ?? values['target-directory']?.[0]
      if (into !== undefined) {
        if (isPathWord(into)) for (const src of o) { if (cmd === 'mv') add(src, 'mv', 'remove'); if (isPathWord(src)) add(joinDir(into, src), cmd) }
      } else if (o.length >= 2) {
        if (cmd === 'mv') for (const src of o.slice(0, -1)) add(src, 'mv', 'remove')
        add(o[o.length - 1] as string, cmd)
      }
    } else if (cmd === 'rm') {
      for (const a of operands(args, { short: '', long: [] }).operands) add(a, 'rm', 'remove')
    } else if (cmd === 'tee') {
      for (const a of operands(args, { short: '', long: [] }).operands) add(a, 'tee')
    } else if (cmd === 'sed') {
      // -i takes its suffix only when attached (GNU) — except BSD's separate empty word (`-i ''`), which is dropped here
      const hasInPlace = args.some((a) => a === '-i' || /^-i./.test(a) || a === '--in-place' || a.startsWith('--in-place='))
      if (hasInPlace) {
        const cleaned = args.filter((a, i) => !(a === '' && args[i - 1] === '-i'))
        const { operands: o, values } = operands(cleaned.map((a) => (/^-i./.test(a) ? '-i' : a)), { short: 'efl', long: ['expression', 'file', 'line-length'] })
        // with -e/-f the script is an option value, so every operand is a file; otherwise the first operand is the script
        const files = values.e || values.f || values.expression || values.file ? o : o.slice(1)
        for (const f of files) add(f, 'sed -i')
      }
    }
    if (seg.op !== '&&') isChainCertain = false
  }
  return out
}

